import math


def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True


def is_multiply_prime(a):
    """Check if a number is the product of exactly three prime numbers."""
    if a <= 2 or a % 3 != 0:
        return False

    # Factorize a
    prime_factors = []
    divisor = 2
    while a > divisor:
        if a % divisor == 0:
            if is_prime(divisor):
                prime_factors.append(divisor)
                a //= divisor
        divisor += 1

    # Check if we have exactly three prime factors
    if len(prime_factors) == 3:
        return True
    return False

```

This implementation assumes that a number cannot be the product of more than three primes, as requested. If a number can have more than three prime factors (e.g., a number that is the product of four prime numbers), the function will return `False`. Adjustments can be made if the requirements change.

