import heapq


def minPath(grid, k):
    n = len(grid)
    dp = [[float('inf')] * n for _ in range(n)]
    parents = [[None] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            dp[i][j] = grid[i][j]

    for k in range(k):
        for i in range(n):
            for j in range(n):
                if dp[i][j] != float('inf'):
                    for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        ni, nj = i + di, j + dj
                        if 0 <= ni < n and 0 <= nj < n:
                            dp[i][j] = min(dp[i][j], grid[i][j] + dp[ni][nj])
                            parents[i][j] = (ni, nj)

    min_path = []
    start = (0, 0)
    for _ in range(k):
        min_path.append(grid[start[0]][start[1]])
        start = parents[start]

    return min_path

