import math


def is_equal_to_sum_even(n):
    """Evaluate whether the given number n can be written as the sum of exactly 4 positive even numbers.

    Args:
    n (int): The number to evaluate.

    Returns:
    bool: True if n can be written as the sum of exactly 4 positive even numbers, False otherwise.
    """

    if n % 2 != 0 or n < 0:
        return False

    for a in range(0, n // 2 + 1, 2):
        for b in range(0, n // 2 + 1, 2):
            for c in range(0, n // 2 + 1, 2):
                for d in range(0, n // 2 + 1, 2):
                    if a + b + c + d == n:
                        return True

    return False

